 68 // patchTargets lists the paths a unified diff names, read from its own `---`
 69 // and `+++` headers and stripped of the usual one-level prefix. git apply is
 70 // what applies the patch; this only needs to know which files it touches.
 71 func patchTargets(patchFile string) ([]string, error) {
 72     data, err := os.ReadFile(patchFile)
 73     if err != nil {
 74         return nil, err
 75     }
 76     var out []string
 77     for _, line := range strings.Split(string(data), "\n") {
 78         var prefix string
 79         switch {
 80         case strings.HasPrefix(line, "--- "):
 81             prefix = "a/"
 82         case strings.HasPrefix(line, "+++ "):
 83             prefix = "b/"
 84         default:
 85             continue
 86         }
 87         target := line[4:]
 88         // diff -u writes a timestamp after a tab; git apply ignores it.
 89         if tab := strings.IndexByte(target, '\t'); tab >= 0 {
 90             target = target[:tab]
 91         }
 92         target = strings.TrimSpace(target)
 93         // A creation names /dev/null on the old side, a deletion on the new
 94         // side. Both sides are read so either way the real path is seen.
 95         if target == "" || target == "/dev/null" {
 96             continue
 97         }
 98         target = path.Clean(strings.TrimPrefix(target, prefix))
 99         if !slices.Contains(out, target) {
100             out = append(out, target)
101         }
102     }
103     return out, nil
104 }
