 92 func refresh(o options) error {
 93     lang, ref, url, subdir := o.Lang, o.Ref, o.URL, o.Subdir
 94     manifestPath, grammarsDir := o.ManifestPath, o.GrammarsDir
 95     if !languageNamePattern.MatchString(lang) {
 96         return fmt.Errorf("invalid -lang %q: use the lower-case directory name under %s", lang, grammarsDir)
 97     }
 98     if subdir != "" && !filepath.IsLocal(subdir) {
 99         return fmt.Errorf("invalid -path %q: must be a relative path inside the repository", subdir)
100     }
101     grammars, err := loadManifest(manifestPath)
102     if err != nil {
103         return err
104     }
105     var existing Grammar
106     for _, g := range grammars {
107         if g.Language == lang {
108             existing = g
109         }
110     }
111     if url == "" {
112         url = existing.URL
113     }
114     if url == "" {
115         return fmt.Errorf("%s is not in %s; pass -url", lang, manifestPath)
116     }
117     if subdir == "" {
118         subdir = existing.Path
119     }
120     if subdir != "" && !filepath.IsLocal(subdir) {
121         return fmt.Errorf("invalid path %q for %s in %s: must be a relative path inside the repository", subdir, lang, manifestPath)
122     }
123     if existing.LocalChanges && !o.AllowLocalChanges {
124         return fmt.Errorf("%s has local changes that a verbatim refresh would discard (%s); pass -allow-local-changes to overwrite it, then reapply them by hand", lang, existing.Note)
125     }
126     build := existing.LocalBuild
127     var patchFile string
128     if build != nil && build.Patch != "" {
129         if !filepath.IsLocal(build.Patch) {
130             return fmt.Errorf("invalid patch %q for %s in %s: must be a relative path inside %s", build.Patch, lang, manifestPath, grammarsDir)
131         }
132         if patchFile, err = filepath.Abs(filepath.Join(grammarsDir, build.Patch)); err != nil {
133             return err
134         }
135     }
136     generating := wantsGeneration(existing, o)
137     if patchFile != "" && !generating {
138         // #357 vendored a Swift parser built from a hand-applied grammar.js
139         // patch, and nothing in the tree said the two were connected. The tool
140         // now applies that patch itself, which is only half the job: applying
141         // it to grammar.js and then copying upstream's committed parser.c
142         // discards it silently and reports success.
143         orphaned, err := patchPathsNeedingGeneration(patchFile)
144         if err != nil {
145             return err
146         }
147         if len(orphaned) > 0 {
148             return fmt.Errorf("%s patches %s, which reaches the vendored grammar only through a regenerated parser; set local_build.tree_sitter_cli for %s in %s, or pass -generate",
149                 build.Patch, strings.Join(orphaned, ", "), lang, manifestPath)
150         }
151     }
152     if generating {
153         if err := findNPX(); err != nil {
154             return err
155         }
156     }
157 
158     tmp, err := os.MkdirTemp("", "grammar-refresh-")
159     if err != nil {
160         return err
161     }
162     defer os.RemoveAll(tmp)
163     if err := git(tmp, "init", "-q"); err != nil {
164         return err
165     }
166     if err := git(tmp, "fetch", "-q", "--depth", "1", "--", url, ref); err != nil {
167         return fmt.Errorf("fetch %s %s: %w", url, ref, err)
168     }
169     if err := git(tmp, "checkout", "-q", "FETCH_HEAD"); err != nil {
170         return err
171     }
172     revision, err := gitOutput(tmp, "rev-parse", "HEAD")
173     if err != nil {
174         return err
175     }
176     if patchFile != "" {
177         if err := applyPatch(tmp, subdir, patchFile); err != nil {
178             return fmt.Errorf("%s at %s: %w", url, ref, err)
179         }
180     }
181     var version string
182     if generating {
183         grammarRoot := filepath.Join(tmp, subdir)
184         if version, err = resolveCLI(grammarRoot, cliVersion(existing, revision, o)); err != nil {
185             return err
186         }
187         args := generateArgs(build)
188         if err := generate(grammarRoot, version, args); err != nil {
189             return err
190         }
191         build = recordedLocalBuild(build, version)
192     }
193 
194     files, abi, err := vendor(tmp, subdir, filepath.Join(grammarsDir, lang))
195     var unsupported abiError
196     if generating && errors.As(err, &unsupported) {
197         return fmt.Errorf("%s at %s: %w; tree-sitter-cli %s may no longer generate ABI %d, so pass -tree-sitter-cli <older version>", url, ref, err, version, maxABI)
198     }
199     if err != nil {
200         return fmt.Errorf("%s at %s: %w", url, ref, err)
201     }
202     grammars = upsert(grammars, Grammar{
203         Language:  lang,
204         URL:       url,
205         Reference: ref,
206         Revision:  revision,
207         Path:      subdir,
208         Files:     files,
209         ABI:       abi,
210         // Kept across a revision change: that is when a note's manual steps
211         // are due. A note the new revision makes obsolete is removed by hand.
212         LocalChanges: existing.LocalChanges,
213         Note:         existing.Note,
214         LocalBuild:   build,
215     })
216     if err := saveManifest(manifestPath, grammars); err != nil {
217         return err
218     }
219     fmt.Printf("vendored %s %s (%s, ABI %d) into %s\n", lang, ref, revision[:7], abi, filepath.Join(grammarsDir, lang))
220     if existing.LocalChanges {
221         fmt.Printf("warning: %s now lacks its local changes; reapply them before committing\n", lang)
222     }
223     if existing.Note != "" {
224         fmt.Printf("note: %s\n", existing.Note)
225     }
226     fmt.Println("next: bump IdentityRevision in internal/sem/provider.go if parse results change, and run scripts/gen-notices.sh")
227     return nil
228 }
