 22 // wantsGeneration reports whether this run regenerates the parser.
 23 func wantsGeneration(existing Grammar, o options) bool {
 24     return o.Generate || o.TreeSitterCLI != "" || (existing.LocalBuild != nil && existing.LocalBuild.TreeSitterCLI != "")
 25 }
 26 
 27 // cliVersion picks the tree-sitter-cli to run: an explicit override, else
 28 // the recorded version when regenerating the recorded revision (so the
 29 // output is reproducible), else latest.
 30 func cliVersion(existing Grammar, revision string, o options) string {
 31     if o.TreeSitterCLI != "" {
 32         return o.TreeSitterCLI
 33     }
 34     if existing.LocalBuild != nil && existing.LocalBuild.TreeSitterCLI != "" && existing.Revision == revision {
 35         return existing.LocalBuild.TreeSitterCLI
 36     }
 37     return "latest"
 38 }
 39 
 40 func generateArgs(build *LocalBuild) []string {
 41     if build != nil && len(build.GenerateArgs) > 0 {
 42         return build.GenerateArgs
 43     }
 44     return defaultGenerateArgs
 45 }
 46 
 47 // resolveCLI turns a version spec such as "latest" into the exact version
 48 // npx runs, so generation and the manifest use the same one.
 49 func resolveCLI(dir, spec string) (string, error) {
 50     out, err := npx(dir, "tree-sitter-cli@"+spec, "--version")
 51     if err != nil {
 52         return "", fmt.Errorf("tree-sitter-cli@%s --version: %w", spec, err)
 53     }
 54     version := cliVersionPattern.FindString(out)
 55     if version == "" {
 56         return "", fmt.Errorf("tree-sitter-cli@%s --version printed no version: %q", spec, out)
 57     }
 58     return version, nil
 59 }
 60 
 61 func generate(grammarRoot, version string, args []string) error {
 62     if _, err := npx(grammarRoot, append([]string{"tree-sitter-cli@" + version, "generate"}, args...)...); err != nil {
 63         return fmt.Errorf("tree-sitter-cli@%s generate: %w; if this release cannot generate ABI %d, pass -tree-sitter-cli <older version>", version, err, maxABI)
 64     }
 65     return nil
 66 }
 67 
 68 // patchTargets lists the paths a unified diff names, read from its own `---`
 69 // and `+++` headers and stripped of the usual one-level prefix. git apply is
 70 // what applies the patch; this only needs to know which files it touches.
 71 func patchTargets(patchFile string) ([]string, error) {
 72     data, err := os.ReadFile(patchFile)
 73     if err != nil {
 74         return nil, err
 75     }
 76     var out []string
 77     for _, line := range strings.Split(string(data), "\n") {
 78         var prefix string
 79         switch {
 80         case strings.HasPrefix(line, "--- "):
 81             prefix = "a/"
 82         case strings.HasPrefix(line, "+++ "):
 83             prefix = "b/"
 84         default:
 85             continue
 86         }
 87         target := line[4:]
 88         // diff -u writes a timestamp after a tab; git apply ignores it.
 89         if tab := strings.IndexByte(target, '\t'); tab >= 0 {
 90             target = target[:tab]
 91         }
 92         target = strings.TrimSpace(target)
 93         // A creation names /dev/null on the old side, a deletion on the new
 94         // side. Both sides are read so either way the real path is seen.
 95         if target == "" || target == "/dev/null" {
 96             continue
 97         }
 98         target = path.Clean(strings.TrimPrefix(target, prefix))
 99         if !slices.Contains(out, target) {
100             out = append(out, target)
101         }
102     }
103     return out, nil
104 }
105 
106 // vendoredDirectly reports whether vendor copies the file at this path, which
107 // is relative to the grammar directory, straight into the grammar folder.
108 // Everything else a patch touches -- grammar.js above all -- reaches the
109 // vendored grammar only through a regenerated parser.
110 func vendoredDirectly(rel string) bool {
111     dir, name := path.Split(rel)
112     upper := strings.ToUpper(name)
113     if strings.HasPrefix(upper, "LICENSE") || strings.HasPrefix(upper, "COPYING") {
114         return dir == ""
115     }
116     switch dir {
117     case "src/":
118         return name == "parser.c" || name == "scanner.c" || strings.HasSuffix(name, ".h")
119     case "src/tree_sitter/":
120         return strings.HasSuffix(name, ".h")
121     }
122     return false
123 }
124 
125 // patchPathsNeedingGeneration lists the paths a patch touches whose effect is
126 // lost unless the parser is regenerated. A patch that only edits vendored
127 // files is a complete change on its own; one that edits grammar.js is not.
128 func patchPathsNeedingGeneration(patchFile string) ([]string, error) {
129     targets, err := patchTargets(patchFile)
130     if err != nil {
131         return nil, err
132     }
133     var out []string
134     for _, t := range targets {
135         if !vendoredDirectly(t) {
136             out = append(out, t)
137         }
138     }
139     return out, nil
140 }
141 
142 // recordedLocalBuild is the local_build block a finished generation writes back
143 // to the manifest: the exact version that ran, and nothing else new.
144 //
145 // GenerateArgs deliberately keeps only what the entry already asked for. The
146 // args actually passed to generate come from generateArgs, which falls back to
147 // --abi maxABI; recording that fallback would turn a derived default into an
148 // explicit pin, and the next runtime bump would edit the one constant while
149 // every grammar went on generating the old ABI -- which vendor keeps accepting
150 // for as long as it is inside the range, so nothing would fail.
151 func recordedLocalBuild(build *LocalBuild, version string) *LocalBuild {
152     next := LocalBuild{}
153     if build != nil {
154         next = *build
155     }
156     next.TreeSitterCLI = version
157     return &next
158 }
 36     LocalBuild   *LocalBuild `json:"local_build,omitempty"`
 37 }
 38 
 39 // LocalBuild is how grammar-refresh turns the upstream checkout into the
 40 // vendored files: Patch (relative to the grammars directory) is applied
 41 // first, then the parser is regenerated when TreeSitterCLI is set.
 42 type LocalBuild struct {
 43     Patch         string   `json:"patch,omitempty"`
 44     TreeSitterCLI string   `json:"tree_sitter_cli,omitempty"`
 45     GenerateArgs  []string `json:"generate_args,omitempty"`
 46 }
 47 
 48 // abiError is a generated parser.c the go-tree-sitter runtime cannot load.
 49 type abiError struct{ abi int }
 50 
 51 func (e abiError) Error() string {
 52     return fmt.Sprintf("grammar is ABI %d, but the go-tree-sitter runtime accepts ABI %d-%d; regenerate it with `tree-sitter generate --abi %d` and vendor the result", e.abi, minABI, maxABI, maxABI)
 53 }
 54 
 55 var languageVersionPattern = regexp.MustCompile(`(?m)^#define LANGUAGE_VERSION (\d+)\s*$`)
 56 
 57 func languageABI(parserC []byte) (int, error) {
 58     m := languageVersionPattern.FindSubmatch(parserC)
 59     if m == nil {
 60         return 0, fmt.Errorf("parser.c has no #define LANGUAGE_VERSION")
 61     }
 62     return strconv.Atoi(string(m[1]))
 63 }
 64 
 65 // vendor copies a generated grammar from repoRoot/subdir into destDir:
 66 // src/parser.c, src/scanner.c when present, src/*.h, src/tree_sitter/*.h and the
 67 // license file as LICENSE (from the grammar directory, else the repository root). Files
 68 // of those kinds already in destDir that the new grammar lacks are removed;
 69 // everything else there, such as binding.go, is left alone. Nothing in destDir
 70 // changes unless the grammar has a parser.c the go-tree-sitter runtime can load.
 71 func vendor(repoRoot, subdir, destDir string) ([]string, int, error) {
 72     grammarRoot := filepath.Join(repoRoot, subdir)
 73     parserC, err := os.ReadFile(filepath.Join(grammarRoot, "src", "parser.c"))
 74     if err != nil {
 75         return nil, 0, fmt.Errorf("no generated %s (pick a ref that ships generated sources)", filepath.ToSlash(filepath.Join(subdir, "src", "parser.c")))
 76     }
 77     abi, err := languageABI(parserC)
 78     if err != nil {
 79         return nil, 0, err
 80     }
 81     if abi < minABI || abi > maxABI {
 82         return nil, 0, abiError{abi}
 83     }
 84 
 85     sources := map[string]string{"parser.c": filepath.Join(grammarRoot, "src", "parser.c")}
 86     if scanner := filepath.Join(grammarRoot, "src", "scanner.c"); fileExists(scanner) {
 87         sources["scanner.c"] = scanner
 88     }
 89     for _, dir := range []string{"", "tree_sitter/"} {
 90         headers, err := filepath.Glob(filepath.Join(grammarRoot, "src", filepath.FromSlash(dir), "*.h"))
 91         if err != nil {
 92             return nil, 0, err
 93         }
 94         for _, h := range headers {
 95             sources[dir+filepath.Base(h)] = h
 96         }
 97     }
 98     license := findLicense(grammarRoot)
 99     if license == "" {
100         license = findLicense(repoRoot)
101     }
102     if license == "" {
103         return nil, 0, fmt.Errorf("no LICENSE or COPYING file in %s or the repository root", grammarRoot)
104     }
105     // Always LICENSE: scripts/gen-notices.sh only attributes files by that name.
106     sources["LICENSE"] = license
107 
108     stale, err := vendoredFiles(destDir)
109     if err != nil {
110         return nil, 0, err
111     }
112     for _, rel := range stale {
113         if _, keep := sources[rel]; !keep {
114             if err := os.Remove(filepath.Join(destDir, filepath.FromSlash(rel))); err != nil {
115                 return nil, 0, err
116             }
117         }
118     }
119     files := make([]string, 0, len(sources))
120     for rel, src := range sources {
121         data, err := os.ReadFile(src)
122         if err != nil {
123             return nil, 0, err
124         }
125         dst := filepath.Join(destDir, filepath.FromSlash(rel))
126         if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
127             return nil, 0, err
128         }
129         if err := os.WriteFile(dst, data, 0o644); err != nil {
130             return nil, 0, err
131         }
132         files = append(files, rel)
133     }
134     sort.Strings(files)
135     return files, abi, nil
136 }
137 
138 func fileExists(path string) bool {
139     info, err := os.Stat(path)
140     return err == nil && !info.IsDir()
141 }
142 
143 func findLicense(dir string) string {
144     entries, err := os.ReadDir(dir)
145     if err != nil {
146         return ""
147     }
148     for _, e := range entries {
149         name := strings.ToUpper(e.Name())
150         if !e.IsDir() && (strings.HasPrefix(name, "LICENSE") || strings.HasPrefix(name, "COPYING")) {
151             return filepath.Join(dir, e.Name())
152         }
153     }
154     return ""
155 }
156 
157 // vendoredFiles lists the files in destDir that vendor manages.
158 func vendoredFiles(destDir string) ([]string, error) {
159     var out []string
160     entries, err := os.ReadDir(destDir)
161     if err != nil {
162         if os.IsNotExist(err) {
163             return nil, nil
164         }
165         return nil, err
166     }
167     for _, e := range entries {
168         name := e.Name()
169         upper := strings.ToUpper(name)
170         switch {
171         case e.IsDir() && name == "tree_sitter":
172             headers, err := filepath.Glob(filepath.Join(destDir, "tree_sitter", "*.h"))
173             if err != nil {
174                 return nil, err
175             }
176             for _, h := range headers {
177                 out = append(out, "tree_sitter/"+filepath.Base(h))
178             }
179         case name == "parser.c" || name == "scanner.c", !e.IsDir() && strings.HasSuffix(name, ".h"),
180             strings.HasPrefix(upper, "LICENSE"), strings.HasPrefix(upper, "COPYING"):
181             out = append(out, name)
182         }
183     }
184     return out, nil
185 }
186 
187 func loadManifest(path string) ([]Grammar, error) {
188     data, err := os.ReadFile(path)
189     if err != nil {
190         if os.IsNotExist(err) {
191             return nil, nil
192         }
193         return nil, err
194     }
195     var grammars []Grammar
196     if err := json.Unmarshal(data, &grammars); err != nil {
197         return nil, fmt.Errorf("%s: %w", path, err)
198     }
199     return grammars, nil
200 }
201 
202 func saveManifest(path string, grammars []Grammar) error {
203     var buf bytes.Buffer
204     enc := json.NewEncoder(&buf)
205     enc.SetEscapeHTML(false)
206     enc.SetIndent("", "  ")
207     if err := enc.Encode(grammars); err != nil {
208         return err
209     }
210     return os.WriteFile(path, buf.Bytes(), 0o644)
211 }
212 
213 // upsert replaces the entry for g.Language, or inserts it, keeping the
214 // manifest sorted by language.
215 func upsert(grammars []Grammar, g Grammar) []Grammar {
216     i := sort.Search(len(grammars), func(i int) bool { return grammars[i].Language >= g.Language })
217     if i < len(grammars) && grammars[i].Language == g.Language {
218         grammars[i] = g
219         return grammars
220     }
221     grammars = append(grammars, Grammar{})
222     copy(grammars[i+1:], grammars[i:])
223     grammars[i] = g
224     return grammars
225 }

